                            visibilityPath: HVAC_Visibility_Priority_Supervisor.VisibilityPathReadiness => B,
                            airPath: HVAC_Visibility_Priority_Supervisor.AirPathReadiness => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val criticalEquipmentValue: HVAC_Visibility_Priority_Supervisor.EquipmentCriticality.Type = get_criticalEquipment().get
    if(!criticalEquipment(criticalEquipmentValue)) {
      testFailures = testFailures :+ st"'criticalEquipment' did not match expected: value of the outgoing data port is ${criticalEquipmentValue}"
    }
    val thermalPathValue: HVAC_Visibility_Priority_Supervisor.ThermalPathReadiness = get_thermalPath().get
    if(!thermalPath(thermalPathValue)) {
      testFailures = testFailures :+ st"'thermalPath' did not match expected: value of the outgoing data port is ${thermalPathValue}"
    }
    val visibilityPathValue: HVAC_Visibility_Priority_Supervisor.VisibilityPathReadiness = get_visibilityPath().get
    if(!visibilityPath(visibilityPathValue)) {
      testFailures = testFailures :+ st"'visibilityPath' did not match expected: value of the outgoing data port is ${visibilityPathValue}"
    }
    val airPathValue: HVAC_Visibility_Priority_Supervisor.AirPathReadiness = get_airPath().get
    if(!airPath(airPathValue)) {
      testFailures = testFailures :+ st"'airPath' did not match expected: value of the outgoing data port is ${airPathValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


